CREATE TABLE IF NOT EXISTS learning_challenges (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL UNIQUE,title VARCHAR(180) NOT NULL,status ENUM('OPEN','SUBMITTED','APPROVED','OVERDUE','WAIVED') NOT NULL DEFAULT 'OPEN',due_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,submitted_at DATETIME,reviewed_by BIGINT UNSIGNED,review_note VARCHAR(1000) NOT NULL DEFAULT '',FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(reviewed_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS challenge_videos (challenge_id BIGINT UNSIGNED PRIMARY KEY,mime VARCHAR(40) NOT NULL,content MEDIUMBLOB NOT NULL,FOREIGN KEY(challenge_id) REFERENCES learning_challenges(id)) ENGINE=InnoDB;
